const stdout = $input.first().json.stdout || '';
try {
  const result = JSON.parse(stdout.trim());
  return [{ json: { ...result, archiveOk: result.status === 'success' } }];
} catch (e) {
  return [{ json: { archiveOk: false, error: 'Failed to parse archive output: ' + e.message, raw: stdout } }];
}

const stdout = $input.first().json.stdout || '';
const lines = stdout.split('\n').filter(l => l.trim());

if (lines.length === 0) {
  return [{ json: { skip: true, reason: 'No files found' } }];
}

const ROOT = '/home/yb/codes/AgentX';

return lines.map(line => {
  const [fullPath, size, modified] = line.split('|');
  const filename = fullPath.split('/').pop();
  const relativePath = fullPath.replace(ROOT, '');
  const ext = filename.split('.').pop().toLowerCase();

  // Auto-tag based on path
  const tags = ['documentation', 'codebase', 'agentx'];
  if (relativePath.includes('/architecture/'))  tags.push('architecture');
  if (relativePath.includes('/operations/'))    tags.push('operations');
  if (relativePath.includes('/patterns/'))      tags.push('patterns');
  if (relativePath.includes('/integrations/'))  tags.push('integrations');
  if (relativePath.includes('/AgentC/'))        tags.push('n8n', 'workflows');
  if (relativePath.includes('/personas/'))      tags.push('personas');
  if (relativePath.includes('/services/'))      tags.push('services');
  if (relativePath.includes('/reports/'))       tags.push('reports');
  if (relativePath.includes('/guides/'))        tags.push('guides');
  if (relativePath.includes('/testing/'))       tags.push('testing');

  return {
    json: {
      path: fullPath,
      relativePath,
      filename,
      extension: ext,
      size: parseInt(size) || 0,
      modified: new Date(parseFloat(modified) * 1000).toISOString(),
      source: 'agentx-complete',
      tags,
      skip: false
    }
  };
});

const executionResults = $input.all();
const originalFiles = $("Filter Skipped").all();

const results = [];
const count = Math.min(executionResults.length, originalFiles.length);

for (let i = 0; i < count; i++) {
  const content = executionResults[i].json.stdout || '';
  const original = originalFiles[i].json;

  if (content.trim()) {
    results.push({
      json: {
        source: original.source || 'agentx-complete',
        path: original.relativePath,
        title: original.filename,
        text: content,
        tags: original.tags || ['documentation', 'codebase'],
        metadata: {
          size: original.size,
          modified: original.modified,
          ingestedAt: new Date().toISOString()
        }
      }
    });
  }
}

return results;

const items = $input.all();
const results = {
  total: items.length,
  success: 0,
  failed: 0,
  errors: []
};

for (const item of items) {
  const res = item.json;
  if (res.status === 'success' || res.status === 'created' || res.status === 'updated' || res.id || res.documentId) {
    results.success++;
  } else {
    results.failed++;
    results.errors.push({ error: res.message || 'Unknown error' });
  }
}

results.timestamp = new Date().toISOString();
results.summary = `N2.4: Ingested ${results.success}/${results.total} codebase markdown files`;

return [{ json: results }];
